    return g.compile()


def run_sequential(ctx):
    """The same graph without LangGraph (used if it cannot be imported)."""

    def step(name):
        ctx.update(NODES[name](ctx) or {})

    step("observe")
    step("route")
    if after_route(ctx) == "menu":
        step("menu")
        nxt = after_menu(ctx)
        if nxt != "close":
            if nxt == "strategist":
                step("strategist")
                step("writer")
            else:
                step(nxt)
            step("critic")
            return ctx
    step("close")
    step("reflect")
    return ctx


